#include <bits/stdc++.h>
using namespace std;
#define ll long long
#define all(x) (x).begin(), (x).end()
const int MOD=1e9+7;

struct Matrix {
    long long a[35][35];
};

Matrix mat_mul(const Matrix &A, const Matrix &B, int size) {
    Matrix C;
    for (int i=0; i<size; i++) {
        for (int j=0; j<size; j++) {
            C.a[i][j]=0;
            for (int k=0; k<size; k++) {
                C.a[i][j]=(C.a[i][j]+A.a[i][k]*B.a[k][j])%MOD;
            }
        }
    }
    return C;
}

Matrix mat_pow(Matrix base, long long exp, int size) {
    Matrix result;
    for (int i=0; i<size; i++) {
        for (int j=0; j<size; j++) {
            result.a[i][j]=(i==j);
        }
    }
    while (exp>0) {
        if (exp&1) result=mat_mul(result, base, size);
        base=mat_mul(base, base, size);
        exp>>=1;
    }
    return result;
}

int main() {
    int n,m;
    cin>>n>>m;
    vector<long long> digits;
    long long tmp=n;
    while (tmp>0) {
        digits.push_back(tmp%m);
        tmp/=m;
    }
    int cnt=digits.size();
    Matrix base, f[75][35], pre[35], suf[35], g;
    memset(&base,0,sizeof(base));
    for (int i=0; i<m; i++) {
        for (int j=0; j<=m; j++) {
            f[0][i].a[j][i]=1;
            f[0][i].a[j][j]=1;
        }
    }
    g.a[0][m]=1;
    for (int i=1; i<=cnt; i++) {
        int idx=cnt - i;
        for (int j=0; j<m; j++) {
            if (i==1 && j==0) {
                pre[j]=f[idx][0];
            } else {
                pre[j]=mat_mul(pre[j-1],f[idx][j],m);
            }
        }
        for (int j=0; j<m; j++) {
            if (j==m-1) {
                suf[j]=f[idx][j];
            } else {
                suf[j]=mat_mul(f[idx][j],suf[j+1],m);
            }
        }
        f[idx+1][0]=suf[0];
        for (int j=1; j<m; j++) {
            f[idx+1][j]=mat_mul(suf[j],pre[j-1],m);
        }
    }
    int cur=0;
    for (int i=cnt-1; i>=0; i--) {
        while (digits[i]--) {
            g=mat_mul(g,f[i][cur],m);
            cur=(cur+1)%m;
        }
    }
    int ans=0;
    for (int i=0; i<=m; i++) {
        ans=(ans+g.a[0][i])%MOD;
    }
    cout<<ans<<endl;
    return 0;
}
